    if "EPA_DHA_total" not in [x["nutriente"] for x in _ficha_seco["faltan"]]:
        fallos.append("BLOQUE21: una dieta de solo pechuga de pollo no da EPA+DHA y el semáforo "
                      "no lo reclama.")

